#ifndef OPENMV_HTML_VIDEO_H
#define OPENMV_HTML_VIDEO_H
// Independent page resource for the HTTP stream server.
static const char HTML_VIDEO_PAGE[] = R"HTML(<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>OpenMV 视频</title><style>body{margin:0;background:#111;color:#fff;font-family:Arial;text-align:center;}.bar{padding:12px;background:#222;}img{display:block;width:100%;height:auto;max-height:90vh;object-fit:contain;}a{color:#fff;text-decoration:none;padding:8px 14px;border-radius:8px;background:#007aff;}</style></head><body><div class='bar'><a id='controlLink' href='/'>返回控制页</a> <span id='state'>视频传输中</span></div><img id='cam' alt='video'><script>const img=document.getElementById('cam'),state=document.getElementById('state');document.getElementById('controlLink').href=location.protocol+'//'+location.hostname+'/';let retry=null;let stopped=false;function load(){if(stopped)return;img.src='/stream?t='+Date.now();}img.onload=function(){state.textContent='视频传输中';};img.onerror=function(){if(stopped)return;state.textContent='重新连接视频…';clearTimeout(retry);retry=setTimeout(load,500);};async function poll(){try{const r=await fetch('/video_status?t='+Date.now(),{cache:'no-store'});const j=await r.json();if(!j.video_active){stopped=true;state.textContent='视频已停止';img.removeAttribute('src');return;}}catch(e){}setTimeout(poll,1000);}load();poll();</script></body></html>)HTML";
#endif
